def solve(nums):
    if not nums:
        return 0

    # Compress coordinates
    sorted_unique = sorted(set(nums))
    compressed = {v: i + 1 for i, v in enumerate(sorted_unique)}  # +1 to avoid 0 index

    class helper1:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, index, value):
            while index <= self.n:
                self.tree[index] = max(self.tree[index], value)
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res = max(res, self.tree[index])
                index -= index & -index
            return res

    ft = helper1(len(compressed))
    max_length = 0

    for num in nums:
        compressed_val = compressed[num]
        # Query the maximum length for all values less than current
        max_before = ft.query(compressed_val - 1)
        # Update the current compressed value with max_before + 1
        ft.update(compressed_val, max_before + 1)
        max_length = max(max_length, max_before + 1)

    return max_length
